import jieba

def tokenize(text: str) -> list:
    # Tokenize input text using jieba
    return list(jieba.cut(text))

def lcs(x: list, y: list) -> int:
    # Compute the length of longest common subsequence of sequences x and y
    m, n = len(x), len(y)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if x[i-1] == y[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[m][n]

